(() => {
  'use strict';
  const D=window.GB_DATA,C=window.GBCore,SESSION=window.GB_SESSION||null,el=id=>document.getElementById(id);
  let savedLanguage='en';try{savedLanguage=localStorage.getItem('gbtor365-language')||'en';}catch{}
  const state={lang:savedLanguage==='es'?'es':'en',view:'overview',user:SESSION?Math.max(0,D.users.findIndex(u=>u.email===SESSION.email)):0,week:0,tab:'invoices',query:'',page:0,validated:{},reviewed:{},approved:{},events:[],uploaded:{ap:null,sales:null},roles:{},importType:'ap',pendingFile:null,workbook:null};
  const t=(en,es)=>state.lang==='es'?es:en;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat(state.lang==='es'?'es-MX':'en-US',{style:'currency',currency:'USD'}).format(n/100);
  const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',invoice:'M6 3h12v18l-3-2-3 2-3-2-3 2V3z M9 7h6 M9 11h6 M9 15h3',chart:'M4 3v17h17 M8 15v-4 M13 15V7 M18 15V4',mapping:'M3 6h7 M14 6h7 M3 18h7 M14 18h7 M10 3v6 M14 15v6 M10 6l4 12',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M12 5v16 M12 5C8 2 4 3 2 4v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-2-10 1',arrow:'M4 12h16 M15 7l5 5-5 5',external:'M14 3h7v7 M10 14L21 3 M21 14v6a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h6',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',check:'M5 12l4 4L19 6',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3z M8 12l3 3 5-6',alert:'M12 3L2 21h20L12 3z M12 9v5 M12 17v.5',file:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9l-7-7z M14 2v7h7 M7 13h10 M7 17h7',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 16v5h16v-5',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',sync:'M4 7h14l-4-4 M20 17H6l4 4 M18 7l-4 4 M6 17l4-4',calendar:'M3 5h18v16H3z M3 10h18 M7 3v4 M17 3v4',menu:'M3 6h18 M3 12h18 M3 18h18',close:'M6 6l12 12 M6 18L18 6',info:'M12 11v6 M12 7v.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 10V4 M3 10h6 M3 10a9 9 0 1 1 1 8',edit:'M14 4l6 6 M4 20l4-1L21 6l-3-3L5 16l-1 4z',folder:'M3 5h6l2 3h10v12H3V5z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 0-6-6L7 5'};
  const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
  const button=(label,action,kind='',ico='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs} ${actionAllowed(action)?'':'disabled'}>${ico?icon(ico,15):''}${label}</button>`;
  const labels={overview:()=>t('Overview','Resumen'),ap:()=>t('Supplier invoices','Facturas de proveedores'),sales:()=>t('Sales journals','Pólizas de ventas'),mapping:()=>t('Mapping rules','Correspondencias'),activity:()=>t('Activity log','Historial'),team:()=>t('Team & access','Equipo y accesos'),guide:()=>t('Workflow guide','Guía de procesos')};
  const roleLabel=r=>({reviewer:t('Review & export','Revisión y exportación'),preparer:t('Sales preparation','Preparación de ventas'),finance:t('Finance oversight','Supervisión financiera'),admin:t('Administrator','Administrador'),viewer:t('Read only','Solo consulta')}[r]||r);
  const user=()=>SESSION||({...D.users[state.user],role:state.roles[state.user]||D.users[state.user].role});
  const initials=(i)=>`<span class="avatar ${['','sage','clay','blue'][i%4]}">${esc((D.users[i]||user()).initials)}</span>`;
  const pill=(label,type='')=>`<span class="pill ${type}">${label}</span>`;
  const ap=()=>state.uploaded.ap||D.ap;
  const sales=()=>state.uploaded.sales||D.sales[state.week];
  const batchKey=kind=>kind==='ap'?(state.uploaded.ap?.id||'ap-sample'):(state.uploaded.sales?.id||'je-'+state.week);
  const summary=kind=>kind==='ap'?C.summarizeAP(ap().rows):C.summarizeJE(sales().rows);
  const issues=kind=>[...new Set(summary(kind).issues.filter(i=>i.level==='review').map(i=>i.code))];
  const currentKind=()=>state.view==='sales'?'sales':'ap';
  const period=s=>{const code=s?.period||'';const m=code.match(/(\d\d)(\d\d)-(\d\d)(\d\d)/);return m?`${t('Oct','oct')} ${+m[2]}–${+m[4]}, 2026`:s?.sheet||t('Uploaded journal','Póliza cargada');};
  function apPeriod(){const dates=ap().rows.map(r=>r.Date).filter(C.validDate).sort((a,b)=>new Date(a)-new Date(b));return dates.length?esc(dates[0]+(dates[0]!==dates.at(-1)?' – '+dates.at(-1):'')):t('Date range unavailable','Período no disponible');}
  function periodReviewText(){const flagged=new Set(summary('sales').issues.filter(i=>i.code==='period').map(i=>i.row));const rows=sales().rows.filter((r,i)=>flagged.has(r._sourceRow||i+2));return esc(t('Journal: ','Póliza: ')+[...new Set(rows.map(r=>r.JENumber))].join('; ')+t('. Source comments: ','. Comentarios de origen: ')+[...new Set(rows.map(r=>r.DetailComment))].join('; '));}
  const allReviewed=kind=>issues(kind).every(code=>(state.reviewed[batchKey(kind)]||[]).includes(code));
  const canApprove=()=>['admin','reviewer','finance'].includes(user().role);
  function actionAllowed(action){
    if(!SESSION)return true;
    const p=SESSION.permissions;
    if(['import','read-file','use-sample'].includes(action))return p.prepare;
    if(['validate','review','save-review'].includes(action))return p.review;
    if(['approve','confirm-approve'].includes(action))return p.approve;
    if(action==='export')return p.export;
    if(['edit-role','save-role'].includes(action))return false;
    return true;
  }
  function toast(text){el('toast').textContent=text;el('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el('toast').classList.remove('visible'),3500);}
  function addEvent(action,detail){state.events.unshift({action,detail,user:user().name,time:new Date().toLocaleTimeString(state.lang==='es'?'es-MX':'en-US',{hour:'2-digit',minute:'2-digit'})});}
  function nav(view){state.view=view;state.query='';state.page=0;state.tab='invoices';history.replaceState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
  function head(title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">ARTIMEX / ${t('FINANCE WORKSPACE','ESPACIO CONTABLE')}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
  function render(){
    document.documentElement.lang=state.lang;
    const u=user();
    el('app').innerHTML=`<div class="shell"><div class="mobile-scrim" data-action="menu"></div><aside class="sidebar" aria-label="${t('Main navigation','Navegación principal')}"><a class="brand" href="#overview" data-nav="overview" aria-label="Artimex overview"><img src="assets/artimex-logo.webp" alt="Artimex Artisan Mexican Bakery"></a><div class="side-product"><span class="product-mark">${icon('sync',22)}</span><div><strong>GBtoR365</strong><small>${t('FINANCE CONNECTION','CONEXIÓN CONTABLE')}</small></div></div><nav class="nav-group"><div class="nav-caption">${t('WORKSPACE','ESPACIO DE TRABAJO')}</div>${['overview','ap','sales','mapping','activity'].map((v,i)=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(['grid','invoice','chart','mapping','clock'][i],17)}${labels[v]()}${v==='sales'&&issues('sales').length?`<span class="nav-count">${issues('sales').length}</span>`:''}</button>`).join('')}</nav><nav class="nav-group"><div class="nav-caption">${t('MANAGEMENT','ADMINISTRACIÓN')}</div>${['team','guide'].map((v,i)=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i?'book':'users',17)}${labels[v]()}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="eyebrow">ARTIMEX CONNECT</div><small>${t('One family of tools.<br>Every process, connected.','Una familia de herramientas.<br>Cada proceso, conectado.')}</small><a href="https://orderstogb.artimexbakery.com/" target="_blank" rel="noopener">EGG Order ${icon('external',13)}</a></div><div class="version"><span>GBtoR365 · v0.1</span><span>${t('Preview','Vista previa')}</span></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="${t('Open menu','Abrir menú')}">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-parent">Artimex</span><span class="crumb-slash">/</span><strong>${labels[state.view]()}</strong></div><div class="top-tools"><span class="mode-badge" title="${t('Interactive prototype','Prototipo interactivo')}">${t('PREVIEW WORKSPACE','ESPACIO DE DEMOSTRACIÓN')}</span><button class="language" data-action="language" aria-label="${t('Switch to Spanish','Cambiar a inglés')}">${state.lang==='en'?'EN':'ES'} ${icon('down',11)}</button><span class="top-divider"></span><button class="user-button" data-action="profile" aria-label="${SESSION?t('Account menu','Menú de cuenta'):t('Switch preview profile','Cambiar perfil de demostración')}">${initials(state.user)}<span><strong>${esc(u.name)}</strong><small>${roleLabel(u.role)}</small></span>${icon('down',12)}</button></div></header><main class="content" id="main">${D.fictional?`<div class="info-strip demo-notice">${icon('info',16)}${t('Fictional demo data · Not real accounting records. Imported files stay in this tab.','Datos ficticios de demostración · No son registros contables reales. Los archivos importados permanecen en esta pestaña.')}</div>`:''}<div class="screen-enter">${({overview:overview,ap:workspace,sales:workspace,mapping:mapping,activity:activity,team:team,guide:guide}[state.view])()}</div><footer class="footer"><span>${icon('lock',11)}${t('Interactive preview. No data is sent to GlobalBake or R365.','Vista interactiva. No se envían datos a GlobalBake ni a R365.')}</span><button data-action="reset">${icon('reset',11)}${t('Reset demo','Reiniciar demo')}</button></footer></main></div></div>`;
  }
  function overview(){
    const a=summary('ap'),s=summary('sales'),checkCount=issues('sales').length;
    return `${head(t('Your accounting, in sync.','Tu contabilidad, conectada.'),t('Prepare, review and export your GlobalBake data from one place.','Prepara, revisa y exporta tus datos de GlobalBake desde un solo lugar.'),button(t('New import','Nueva importación'),'import','primary','plus'))}<section class="hero-panel"><div class="hero-copy"><div class="eyebrow">${t('FROM OPERATIONS TO ACCOUNTING','DE LA OPERACIÓN A LA CONTABILIDAD')}</div><h2>${t('A clear path from<br>GlobalBake to R365.','Un camino claro de<br>GlobalBake a R365.')}</h2><p>${t('Two workflows. One review process.<br>Every figure traceable to its source.','Dos procesos. Una misma revisión.<br>Cada cifra se puede rastrear hasta su origen.')}</p></div><div class="hero-route" aria-label="GlobalBake to GBtoR365 to Restaurant365"><div class="route-node"><b>GlobalBake</b><small>${t('SOURCE FILES','ARCHIVOS DE ORIGEN')}</small></div><div class="route-line"></div><div class="route-center">${icon('sync',20)}</div><div class="route-line"></div><div class="route-node r365"><b>R365</b><small>${t('REVIEWED EXPORT','EXPORTACIÓN REVISADA')}</small></div></div></section><section class="stats" aria-label="${t('Source file summary','Resumen de archivos')}">${stat(t('Supplier invoices','Facturas de proveedores'),a.count,money(a.total)+' USD','invoice')}${stat(t('Sales invoice references','Referencias de venta'),sales().invoices?.length||'—',period(sales()),'chart')}${stat(t('Journal balance','Balance de la póliza'),money(s.difference),s.difference?t('Debits and credits differ','Débitos y créditos no coinciden'):t('Debits match credits','Débitos y créditos coinciden'),'check')}${stat(t('Review checkpoints','Puntos de revisión'),checkCount,t('In the selected sales journal','En la póliza de ventas seleccionada'),'alert',true)}</section><div class="section-line"><h2>${t('Choose your workflow','Elige tu proceso')}</h2><span class="period-label">${icon('calendar',13)}${state.uploaded.ap||state.uploaded.sales?t('Current files · Local preview','Archivos actuales · Vista local'):t('October 2026 · Fictional demo samples','Octubre 2026 · Ejemplos ficticios')}</span></div><div class="workflow-grid"><section class="workflow-card"><div class="workflow-heading"><span class="workflow-icon">${icon('invoice',22)}</span>${pill(t('AP INVOICES','FACTURAS AP'))}</div><h3>${t('Supplier invoices','Facturas de proveedores')}</h3><p>${t('Review purchase invoices and their account allocations before preparing the R365 file.','Revisa las facturas de compra y su distribución contable antes de preparar el archivo R365.')}</p><div class="workflow-meta"><span>${a.count} ${t('invoices','facturas')}</span><span>${a.lines} ${t('account lines','líneas contables')}</span><span>${a.vendors} ${t('vendors','proveedores')}</span></div><div class="workflow-footer"><span class="person-mini">${initials(0)}${esc((D.users.find(u=>u.role==='reviewer')||user()).name)}</span>${button(t('Open workflow','Abrir proceso'),'go-ap','small','arrow')}</div></section><section class="workflow-card sales"><div class="workflow-heading"><span class="workflow-icon">${icon('chart',22)}</span>${pill(t('SALES JOURNALS','PÓLIZAS DE VENTAS'),'amber')}</div><h3>${t('Weekly sales journals','Pólizas de ventas semanales')}</h3><p>${t('Reconcile invoices, review account totals and prepare the weekly journal for R365.','Concilia facturas, revisa los totales por cuenta y prepara la póliza semanal para R365.')}</p><div class="workflow-meta"><span>${money(s.debit)} USD</span><span>${s.activeLines} ${t('active lines','líneas con importe')}</span></div><div class="workflow-footer"><span class="person-mini">${initials(1)}${esc((D.users.find(u=>u.role==='preparer')||user()).name)} → ${esc((D.users.find(u=>u.role==='reviewer')||user()).name)}</span>${button(t('Open workflow','Abrir proceso'),'go-sales','small','arrow')}</div></section></div><div class="dashboard-lower"><section class="panel"><div class="panel-heading"><h2>${t('Current review queue','Pendientes de revisión')}</h2>${pill(t('DEMO SAMPLES','EJEMPLOS FICTICIOS'),'outline')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Batch','Lote')}</th><th>${t('Value','Importe')}</th><th>${t('Status','Estado')}</th><th></th></tr></thead><tbody><tr><td><span class="row-title">${t('Vendor transactions','Transacciones de proveedores')}</span><small>AP · ${apPeriod()}</small></td><td class="money">${money(a.total)}</td><td>${pill(state.approved[batchKey('ap')]?t('Approved preview','Vista aprobada'):t('Ready to review','Listo para revisar'))}</td><td><button class="icon-btn" data-nav="ap" aria-label="${t('Review supplier invoices','Revisar facturas de proveedores')}">${icon('chevron',14)}</button></td></tr><tr><td><span class="row-title">${t('Weekly sales journal','Póliza de ventas semanal')}</span><small>JE · ${period(sales())}</small></td><td class="money">${money(s.debit)}</td><td>${pill(allReviewed('sales')?t('Reviewed','Revisado'):`${checkCount} ${t('checks','revisiones')}`,'amber')}</td><td><button class="icon-btn" data-nav="sales" aria-label="${t('Review sales journal','Revisar póliza de ventas')}">${icon('chevron',14)}</button></td></tr></tbody></table></div><div class="table-foot"><span>${t('Fictional demo amounts · USD','Importes ficticios de demostración · USD')}</span><button class="text-button" data-nav="activity">${t('Activity log','Ver historial')} ${icon('arrow',12)}</button></div></section><section class="panel"><div class="panel-heading"><h2>${t('Your next steps','Próximos pasos')}</h2>${icon('clock',15)}</div><div class="panel-body"><div class="timeline">${timeline('check',t('Review supplier invoices','Revisar facturas de proveedores'),t(`${a.count} invoice totals checked against their account lines.`, `Los totales de ${a.count} facturas se comparan con sus líneas contables.`))}${timeline('alert',t('Check the sales journal','Revisar la póliza de ventas'),t('Review negative entries and previous-period comments.','Revisar importes negativos y comentarios del período anterior.'),'amber')}${timeline('download',t('Prepare an export preview','Preparar una vista de exportación'),t('Validate the batch and download a review copy.','Valida el lote y descarga una copia para revisión.'))}</div><div class="activity-note">${t('The preview demonstrates the process. Import results will require a connection to R365.','La vista previa demuestra el proceso. Los resultados de importación requieren conexión con R365.')}</div></div></section></div>`;
  }
  function stat(label,value,note,ico,warn=false){return `<div class="stat ${warn?'warn':''}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico,14)}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
  function timeline(ico,title,desc,kind=''){return `<div class="timeline-item"><span class="timeline-dot ${kind}">${icon(ico,12)}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`;}
  function workspace(){
    const kind=currentKind(),isAP=kind==='ap',data=isAP?ap():sales(),sum=summary(kind),key=batchKey(kind),errorCount=sum.issues.filter(i=>i.level==='error').length;
    const checks=issues(kind),reviewed=allReviewed(kind),approved=state.approved[key];
    const name=isAP?data.source:(data.source||D.sourceWorkbook);
    return `${head(labels[kind](),isAP?t('GlobalBake purchases → R365 Vendor Transaction by Account','Compras GlobalBake → R365 Vendor Transaction by Account'):t('GlobalBake G/L transactions → R365 Journal Entry','Transacciones GlobalBake G/L → R365 Journal Entry'),`<div class="button-row">${!isAP&&!state.uploaded.sales?`<select class="select" id="week-select" aria-label="${t('Select sales week','Elegir semana de ventas')}">${D.sales.map((s,i)=>`<option value="${i}" ${i===state.week?'selected':''}>${period(s)}</option>`).join('')}</select>`:''}${button(t('Import file','Importar archivo'),'import','primary','upload',`data-kind="${kind}"`)}</div>`)}<div class="workflow-steps">${[t('Import','Importar'),t('Review','Revisar'),t('Validate','Validar'),t('Export','Exportar')].map((s,i)=>`<div class="step ${i<= (approved?3:state.validated[key]?2:1)?'active':''}"><i>${i===0?icon('check',11):i+1}</i>${s}</div>`).join('')}</div><div class="workspace-grid"><div class="panel"><div class="file-bar"><div class="file-info"><span class="file-icon">${icon('file',20)}</span><div><strong>${esc(name)}</strong><small>${isAP?`${sum.lines} ${t('detail rows','filas de detalle')} · ${sum.vendors} ${t('vendors','proveedores')}`:`${esc(data.sheet)} · ${sum.lines} ${t('journal rows','filas de póliza')}`} · ${t('Source data','Datos de origen')}</small></div></div>${pill(t('LOCAL PREVIEW','VISTA LOCAL'),'outline')}</div><div class="tabs">${['invoices','lines','export'].map((tab,i)=>`<button class="tab ${state.tab===tab?'active':''}" data-tab="${tab}">${[t('Invoice overview','Resumen de facturas'),isAP?t('Account detail','Detalle por cuenta'):t('Journal entries','Asientos contables'),t('R365 preview','Vista R365')][i]}</button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search',14)}<input id="table-search" value="${esc(state.query)}" placeholder="${isAP?t('Search invoice or vendor…','Buscar factura o proveedor…'):t('Search invoice or account…','Buscar factura o cuenta…')}" aria-label="${t('Search records','Buscar registros')}"></label><span class="pill outline">${isAP?'AP INVOICE':'Standard JE'} · USD</span></div><div id="records-region">${records()}</div></div><aside class="workspace-sidebar"><section class="panel"><div class="panel-heading"><h2>${t('Batch controls','Controles del lote')}</h2>${icon('shield',17)}</div><div class="panel-body"><div class="balance-box">${isAP?`<div class="balance-row"><span>${t('Invoice totals','Totales de facturas')}</span><span class="money">${money(sum.total)}</span></div><div class="balance-row"><span>${t('Detail totals','Totales del detalle')}</span><span class="money">${money(sum.groups.reduce((n,g)=>n+g.detail,0))}</span></div><div class="balance-row"><span>${t('Difference','Diferencia')}</span><span>${money(sum.groups.reduce((n,g)=>n+g.detail-g.amount,0))}</span></div>`:`<div class="balance-row"><span>${t('Debits','Débitos')}</span><span class="money">${money(sum.debit)}</span></div><div class="balance-row"><span>${t('Credits','Créditos')}</span><span class="money">${money(sum.credit)}</span></div><div class="balance-row"><span>${t('Difference','Diferencia')}</span><span>${money(sum.difference)}</span></div>`}</div>${checkItem('check',t('Expected columns found','Columnas esperadas presentes'),isAP?'14 · Vendor Transaction by Account':'11 · Journal Entry')}${checkItem(errorCount?'alert':'check',errorCount?t(`${errorCount} validation errors`,`${errorCount} errores de validación`):t('Totals reconciled','Totales conciliados'),isAP?t('Each invoice checked independently','Cada factura se revisa por separado'):t('Checked by journal number','Comprobado por número de póliza'),errorCount?'error':'')}${checks.map(code=>checkItem((state.reviewed[key]||[]).includes(code)?'check':'alert',issueTitle(code),issueDescription(code),reviewed?'':'review')).join('')}${checks.length?`<div style="margin-top:13px">${button(reviewed?t('View review notes','Ver notas de revisión'):t(`Review ${checks.length} checkpoints`,`Revisar ${checks.length} puntos`),'review','full small','alert')}</div>`:''}<div style="margin-top:14px">${button(state.validated[key]?t('Run checks again','Repetir controles'):t('Validate batch','Validar lote'),'validate','full','shield')}</div></div></section><section class="panel"><div class="panel-heading"><h2>${t('Review & export','Revisión y exportación')}</h2>${initials(0)}</div><div class="panel-body">${approved?`<div class="info-strip">${icon('check',14)}${t('Approved in this preview session.','Aprobado en esta sesión de demostración.')}</div>${button(t('Download preview CSV','Descargar CSV de vista previa'),'export','primary full','download',canApprove()?'':'disabled')}`:`<p class="notice">${t('Confirm the figures and review notes before preparing the export.','Confirma los importes y las notas de revisión antes de preparar la exportación.')}</p>${!canApprove()?`<div class="review-note">${t('This proposed role prepares data. Switch to a reviewer or finance profile to review and approve the preview.','Este rol propuesto prepara los datos. Cambia a un perfil de revisión o finanzas para revisar y aprobar la vista previa.')}</div>`:''}${button(t('Approve preview','Aprobar vista previa'),'approve','primary full','check',(!state.validated[key]||!reviewed||errorCount||!canApprove())?'disabled':'')}`}<p class="small-note">${t('Downloading does not import or post any transaction in R365.','Descargar no importa ni registra transacciones en R365.')}</p></div></section></aside></div>`;
  }
  function checkItem(ico,title,desc,kind=''){return `<div class="check-item ${kind}">${icon(ico,14)}<div><strong>${title}</strong><small>${desc}</small></div></div>`;}
  function issueTitle(code){return {negative:t('Negative amounts in source','Importes negativos en el origen'),period:t('Previous-period comments','Comentarios del período anterior'),locations:t('Multiple R365 locations','Varias ubicaciones R365')}[code]||code;}
  function issueDescription(code){return {negative:t('Preserved for accounting review.','Conservados para revisión contable.'),period:t('Check comments against the selected week.','Comprobar los comentarios contra la semana elegida.'),locations:t('Confirm location allocations before export.','Confirmar la distribución por ubicación.')}[code]||t('Review the source file.','Revisar el archivo original.');}
  function records(){
    const kind=currentKind(),isAP=kind==='ap',data=isAP?ap():sales(),sum=summary(kind),q=state.query.toLowerCase();let rows=[],headers=[],renderRow;
    if(state.tab==='export'){
      headers=isAP?C.AP_HEADERS:C.JE_HEADERS;rows=data.rows;renderRow=r=>`<tr>${headers.map(h=>`<td>${esc(r[h])}</td>`).join('')}</tr>`;
    }else if(state.tab==='invoices'&&isAP){
      headers=[t('Invoice / vendor','Factura / proveedor'),t('Date','Fecha'),t('Location','Ubicación'),t('Total','Total'),t('Control','Control'),''];rows=sum.groups;
      renderRow=(r,i)=>`<tr><td><span class="row-title">${esc(r.number)}</span><small>${esc(r.vendor)} · ${r.rows.length} ${t('lines','líneas')}</small></td><td>${esc(r.date)}</td><td>${esc(r.location)}</td><td class="money">${money(r.amount)}</td><td>${pill(r.amount===r.detail?t('Reconciled','Conciliado'):t('Mismatch','Diferencia'),r.amount===r.detail?'':'red')}</td><td><button class="icon-btn" data-action="detail" data-number="${esc(r.number)}" data-vendor="${esc(r.vendor)}" data-location="${esc(r.location)}" aria-label="${t('Open invoice','Abrir factura')} ${esc(r.number)}">${icon('chevron',12)}</button></td></tr>`;
    }else if(state.tab==='invoices'&&!isAP){
      rows=data.invoices||[];headers=[t('Invoice','Factura'),t('Customer','Cliente'),t('Date','Fecha'),t('Account','Cuenta'),t('Amount','Importe')];
      renderRow=r=>`<tr class="${C.cents(r.amount)<0?'flagged':''}"><td><span class="row-title">${esc(r.number)}</span><small>${t('Source row','Fila de origen')} ${r.sourceRow}</small></td><td>${esc(r.customer)}</td><td>${esc(r.date)}</td><td>${esc(r.account)}</td><td class="money ${C.cents(r.amount)<0?'negative':''}">${money(C.cents(r.amount))}</td></tr>`;
    }else if(isAP){
      rows=data.rows;headers=[t('Invoice','Factura'),t('Vendor','Proveedor'),t('Account','Cuenta'),t('Detail location','Ubicación detalle'),t('Detail amount','Importe detalle')];renderRow=r=>`<tr><td class="row-title">${esc(r.Number)}</td><td>${esc(r.Vendor)}</td><td>${esc(r['Detail Account'])}</td><td>${esc(r['Detail Location'])}</td><td class="money">${money(C.cents(r['Detail Amount']))}</td></tr>`;
    }else{
      rows=data.rows;headers=[t('Row','Fila'),t('Account','Cuenta'),t('Description','Descripción'),t('Debit','Débito'),t('Credit','Crédito')];renderRow=r=>`<tr class="${C.cents(r.Debit)<0||C.cents(r.Credit)<0?'flagged':''}"><td>${r._sourceRow||'—'}</td><td class="row-title">${esc(r.Account)}<small>${esc(r.DetailLocation)}</small></td><td>${esc(r.DetailComment)}</td><td class="money ${C.cents(r.Debit)<0?'negative':''}">${r.Debit?money(C.cents(r.Debit)):'—'}</td><td class="money ${C.cents(r.Credit)<0?'negative':''}">${r.Credit?money(C.cents(r.Credit)):'—'}</td></tr>`;
    }
    const filtered=q?rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q)):rows;
    const pages=Math.max(1,Math.ceil(filtered.length/9));state.page=Math.min(state.page,pages-1);const start=state.page*9,show=filtered.slice(start,start+9);
    return `${state.tab==='export'?`<div class="info-strip" style="margin:15px 20px">${icon('info',14)}${t('Review layout only. Values and signs are preserved from the source.','Sólo vista de revisión. Se conservan los valores y signos del origen.')}</div>`:''}<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${show.map(renderRow).join('')||`<tr><td colspan="${headers.length}" class="empty">${t('No matching records.','No hay registros que coincidan.')}</td></tr>`}</tbody></table></div><div class="table-foot"><span>${filtered.length?start+1:0}–${Math.min(start+9,filtered.length)} ${t('of','de')} ${filtered.length} ${t('records','registros')}</span><div class="pager"><button data-action="page-prev" ${state.page===0?'disabled':''} aria-label="${t('Previous page','Página anterior')}">‹</button><span style="padding:4px">${state.page+1} / ${pages}</span><button data-action="page-next" ${state.page+1>=pages?'disabled':''} aria-label="${t('Next page','Página siguiente')}">›</button></div></div>`;
  }
  function mapping(){return `${head(t('Consistent data, every time.','Datos consistentes, siempre.'),t('Rules identified in the supplied procedures. Confirm them before connecting live systems.','Reglas identificadas en los procedimientos recibidos. Confírmalas antes de conectar los sistemas.'))}<div class="info-strip">${icon('info',16)}${t('These are proposed mapping rules, not live configuration. R365 location codes are accounting codes; they are not EGG restaurant names.','Son reglas propuestas, no configuración activa. Los códigos de ubicación R365 son códigos contables; no son nombres de restaurantes EGG.')}</div><div class="rules-grid"><section class="panel"><div class="panel-heading"><h2>${t('Supplier invoice rules','Reglas de facturas de proveedores')}</h2>${pill('AP')}</div>${rule(t('Normalize account codes','Normalizar códigos contables'),t('Remove the 0092- prefix and the final three zeros for the documented format only.','Eliminar el prefijo 0092- y los tres ceros finales sólo en el formato documentado.'),'0092-55120000','55120')}${rule(t('Preserve invoice references','Conservar referencias de factura'),t('Keep vendor codes, invoice suffixes and leading zeros as text.','Conservar códigos de proveedor, sufijos y ceros iniciales como texto.'),'00450097JA','00450097JA')}${rule(t('Separate headers and account lines','Separar cabeceras y detalle'),t('Carry the invoice total into Amount; reconcile the sum of Detail Amount for each invoice. Raw MYOB H/D records need a full source sample.','Llevar el total a Amount y conciliar Detail Amount por factura. Los registros H/D de MYOB requieren un archivo original completo.'),'Amount','Σ Detail Amount')}${rule(t('Confirm the location mapping','Confirmar la ubicación'),t('The procedure shows store 0092 and the template uses EGG70. This link must be confirmed by the team.','El procedimiento muestra store 0092 y la plantilla utiliza EGG70. El equipo debe confirmar esta correspondencia.'),'0092','EGG70 ?')}</section><section class="panel"><div class="panel-heading"><h2>${t('Sales journal rules','Reglas de pólizas de ventas')}</h2>${pill('JE','amber')}</div>${rule(t('Use the G/L Transaction Report','Usar G/L Transaction Report'),t('Select the date range and keep Type = Sale, as described in the supplied procedure. Retain excluded rows in the future audit trail.','Elegir el período y conservar Type = Sale, como indica el procedimiento. En producción se guardarán las filas excluidas en el historial.'),'Type','Sale')}${rule(t('Group by invoice and account','Agrupar por factura y cuenta'),t('Preserve customer, invoice reference, date and account assignments while building the journal.','Conservar cliente, referencia de factura, fecha y cuentas al generar la póliza.'),'Invoice + account','Journal lines')}${rule(t('Reconcile debits and credits','Conciliar débitos y créditos'),t('Check each journal number in cents and flag a nonzero difference. Preserve negative signs for review.','Comprobar cada póliza en centavos y señalar diferencias. Conservar los signos negativos para revisión.'),'Σ Debit','Σ Credit')}${rule(t('Review period comments','Revisar comentarios del período'),t('The Oct 19–25 sample includes comments referring to Oct 12–18. Show both values before any correction.','El ejemplo del 19–25 oct incluye comentarios del 12–18 oct. Mostrar ambos valores antes de corregir.'),'10/19–10/25','10-12/10-18')}</section></div><div class="panel" style="margin-top:20px"><div class="panel-heading"><h2>${t('Demo customer accounts','Cuentas ficticias de clientes')}</h2>${pill(t('REFERENCE','REFERENCIA'),'outline')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Customer','Cliente')}</th><th>${t('Account','Cuenta')}</th><th>${t('Source','Origen')}</th></tr></thead><tbody>${[...new Map(D.sales.flatMap(w=>w.invoices||[]).map(r=>[r.customer,[r.customer,r.account]])).values()].map(r=>`<tr><td class="row-title">${esc(r[0])}</td><td>${esc(r[1])}</td><td>${esc(D.sourceWorkbook)}</td></tr>`).join('')}</tbody></table></div></div>`;}
  function rule(title,desc,from,to){return `<div class="rule"><strong>${title}</strong><p>${desc}</p><div class="rule-example"><span>${from}</span>${icon('arrow',14)}<span>${to}</span></div></div>`;}
  function activity(){return `${head(t('A record of every step.','Un registro de cada paso.'),t('Actions performed in this preview session, separate from the original source files.','Acciones realizadas en esta sesión de demostración, separadas de los archivos originales.'),button(t('Download log','Descargar historial'),'download-log','','download'))}<div class="panel"><div class="panel-heading"><h2>${t('Session activity','Actividad de la sesión')}</h2>${pill(t('DEMO LOG','HISTORIAL DEMO'),'outline')}</div>${state.events.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Time','Hora')}</th><th>${t('Action','Acción')}</th><th>${t('Details','Detalles')}</th><th>${t('Preview profile','Perfil de vista previa')}</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${esc(e.time)}</td><td class="row-title">${esc(e.action)}</td><td>${esc(e.detail)}</td><td>${esc(e.user)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('clock',32)}<h3>${t('Your review starts here','Tu revisión comienza aquí')}</h3><p>${t('Validate a batch or download a preview to see the action recorded here.','Valida un lote o descarga una vista previa para registrar la acción aquí.')}</p></div>`}</div><div class="info-strip" style="margin-top:20px">${icon('info',15)}${t('Preview history stays in this tab and resets on reload. A production version will need persistent audit records and confirmed R365 import receipts.','El historial permanece en esta pestaña y se reinicia al recargar. La versión de producción requerirá un historial persistente y confirmaciones de importación de R365.')}</div>`;}
  function team(){if(SESSION)return activeTeam();return `${head(t('The right people, in the loop.','El equipo correcto, conectado.'),SESSION?t('Your administrator account and proposed workflow profiles.','Tu cuenta de administrador y perfiles propuestos del proceso.'):t('Fictional profiles demonstrate the proposed Artimex roles.','Perfiles ficticios para demostrar los roles propuestos de Artimex.'))}<div class="user-grid">${D.users.map((u,i)=>`<section class="user-card"><div class="user-card-head">${initials(i)}<div><h3>${esc(u.name)}</h3><span class="email">${esc(u.email)}</span></div></div><p>${[t('Review supplier invoices and sales journals, then prepare R365 exports.','Revisar facturas y pólizas de ventas, y preparar las exportaciones R365.'),t('Prepare weekly sales data and submit the journal for accounting review.','Preparar las ventas semanales y entregar la póliza para revisión contable.'),t('Oversee financial controls and review exceptions before production use.','Supervisar controles financieros y revisar excepciones antes de producción.'),t('Configure integrations, mappings and future access permissions.','Configurar integraciones, correspondencias y futuros permisos.')][i]}</p><div class="user-card-footer">${pill(roleLabel(state.roles[i]||u.role),i===1?'amber':'')}<button class="text-button" data-action="edit-role" data-user="${i}">${icon('edit',12)}${t('Edit role','Editar rol')}</button></div><p class="source-label" style="margin:13px 0 0">${SESSION&&i===3?t('Administrator account · Active','Cuenta de administrador · Activa'):t('Fictional profile · No invitation sent','Perfil ficticio · Sin invitación enviada')}</p></section>`).join('')}</div><div class="info-strip" style="margin-top:20px">${icon('users',16)}${t('Use the profile menu to try each proposed role. This switch demonstrates the interface; it is not authentication.','Usa el menú de perfil para probar cada rol propuesto. El cambio demuestra la interfaz; no es autenticación.')}</div>`;}
  function activeTeam(){return `${head(t('Team & access','Equipo y accesos'),t('Active GBtoR365 accounts and their assigned access.','Cuentas activas de GBtoR365 y sus accesos asignados.'))}<div class="user-grid">${D.users.map((u,i)=>`<section class="user-card"><div class="user-card-head">${initials(i)}<div><h3>${esc(u.name)}</h3><span class="email">${esc(u.email)}</span></div></div><div class="user-card-footer">${pill(roleLabel(u.role))}${pill(t('Active account','Cuenta activa'),'outline')}</div><p class="source-label" style="margin:13px 0 0">${u.email===SESSION.email?t('Your account','Tu cuenta'):t('Individual account','Cuenta individual')}</p></section>`).join('')}</div><div class="info-strip" style="margin-top:20px">${icon('lock',16)}${t('Access is assigned on the server. Contact your administrator to change an account.','Los accesos se asignan en el servidor. Contacta a tu administrador para modificar una cuenta.')}</div>`;}
  function guide(){return `${head(t('From source file to review copy.','Del archivo original a la revisión.'),t('A workflow built around the procedures supplied by your team.','Un proceso basado en los procedimientos compartidos por tu equipo.'))}<div class="guide-grid"><section class="panel"><div class="panel-heading"><h2>${t('Supplier purchases','Compras a proveedores')}</h2>${icon('invoice',17)}</div><div class="panel-body">${guideStep(1,t('Export from GlobalBake','Exportar desde GlobalBake'),t('Week/Month → Platinum MYO Export → select week → Export Purchase. Keep the original AP0001 text file.','Week/Month → Platinum MYO Export → elegir semana → Export Purchase. Conservar el archivo AP0001 original.'))}${guideStep(2,t('Normalize and map','Normalizar y asignar'),t('Format dates, carry invoice totals, normalize documented GL codes and map vendors and locations.','Formatear fechas, conservar totales, normalizar códigos GL documentados y asignar proveedores y ubicaciones.'))}${guideStep(3,t('Reconcile the invoice','Conciliar la factura'),t('The sum of the account detail must match the invoice total. Keep the original invoice number.','La suma del detalle contable debe coincidir con el total de la factura. Conservar el número original.'))}${guideStep(4,t('Review the R365 layout','Revisar el formato R365'),t('The preview loads the supplied Vendor Transaction by Account CSV. The raw MYOB converter remains a development step.','La demo carga el CSV Vendor Transaction by Account recibido. El convertidor MYOB original queda como desarrollo siguiente.'))}</div></section><section class="panel"><div class="panel-heading"><h2>${t('Weekly sales','Ventas semanales')}</h2>${icon('chart',17)}</div><div class="panel-body">${guideStep(1,t('Export the G/L report','Exportar el reporte G/L'),t('Ledger → Reports → G/L Transaction Report. Select dates and export the report.','Ledger → Reports → G/L Transaction Report. Elegir fechas y exportar.'))}${guideStep(2,t('Prepare the sales data','Preparar las ventas'),t('Keep Sale rows, add the customer mapping, and group amounts by invoice and account.','Conservar filas Sale, asignar clientes y agrupar importes por factura y cuenta.'))}${guideStep(3,t('Review the journal','Revisar la póliza'),t('Reconcile debit and credit totals. Review negative amounts, location assignments and date comments.','Conciliar débitos y créditos. Revisar negativos, ubicaciones y comentarios de fechas.'))}${guideStep(4,t('Prepare the export','Preparar la exportación'),t('The preparer provides the report for the reviewer to import into R365. This preview can read the supplied XLSX journal sheets and prepare CSV review copies.','La persona preparadora entrega el reporte a la persona revisora para importarlo a R365. La demo lee las hojas de pólizas del XLSX recibido y prepara copias CSV de revisión.'))}</div></section></div><div class="panel" style="margin-top:20px"><div class="panel-heading"><h2>${t('Source documents','Documentos de referencia')}</h2>${pill('4','outline')}</div><div class="panel-body"><div class="source-files">${[D.ap.source,D.sourceWorkbook,'Procedimiento para importar invoice GlobalBake - R365.pdf','GB Vendor Purchas invoice to R365.docx'].map(f=>`<div class="source-file">${icon('file',15)}${esc(f)}</div>`).join('')}</div><p class="small-note">${t('The documents inform this preview. Automatic retrieval from GB and submission to R365 are not connected.','Los documentos orientan esta demo. La recuperación automática de GB y el envío a R365 aún no están conectados.')}</p></div></div>`;}
  function guideStep(n,title,desc){return `<div class="guide-step"><span class="guide-number">${n}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`;}
  function showDialog(title,body,footer=''){
    const modal=el('modal');modal.innerHTML=`<div class="dialog-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="${t('Close dialog','Cerrar ventana')}">${icon('close',17)}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();
  }
  function openImport(kind='ap'){
    state.importType=kind;state.pendingFile=null;state.workbook=null;
    showDialog(t('Start a new import','Iniciar una importación'),`<p class="notice">${t('Files are read locally in your browser. Nothing is sent to either system.','Los archivos se leen localmente en tu navegador. No se envían a ninguno de los sistemas.')}</p><div class="form-row"><label class="form-field">${t('Workflow','Proceso')}<select id="import-kind"><option value="ap" ${kind==='ap'?'selected':''}>${t('Supplier invoices · AP','Facturas de proveedores · AP')}</option><option value="sales" ${kind==='sales'?'selected':''}>${t('Sales journals · JE','Pólizas de ventas · JE')}</option></select></label><label class="form-field">${t('Prepared by','Preparado por')}<input readonly value="${esc(user().name)}"></label></div><label class="dropzone" id="dropzone"><input type="file" id="upload-file" accept=".csv,.tsv,.txt,.xlsx" aria-label="${t('Choose a source file','Elegir archivo de origen')}">${icon('upload',27)}<strong id="upload-name">${t('Drop a file here, or browse','Arrastra un archivo o haz clic')}</strong><small>${t('R365 AP CSV or sales journal XLSX / CSV · Up to 10 MB','CSV de facturas R365 o póliza XLSX / CSV · Hasta 10 MB')}</small></label><div id="file-options"></div><div id="upload-error"></div><p class="small-note">${t('For the prototype, use the supplied R365 template or a journal worksheet. Raw GlobalBake exports need a dedicated converter.','Para el prototipo usa la plantilla R365 recibida o una hoja de pólizas. Los exports originales de GlobalBake requieren un convertidor específico.')}</p>`,button(t('Use demo sample','Usar ejemplo de demostración'),'use-sample')+button(t('Read & review file','Leer y revisar archivo'),'read-file','primary','arrow','disabled id="read-file-btn"'));
  }
  async function selectFile(file){
    if(!file)return;state.pendingFile=file;state.workbook=null;el('upload-error').innerHTML='';el('upload-name').textContent=file.name;el('file-options').innerHTML='';
    try{
      if(file.size>10*1024*1024)throw Error(t('Maximum file size: 10 MB.','Tamaño máximo: 10 MB.'));
      if(/\.xlsx$/i.test(file.name)){
        el('read-file-btn').disabled=true;state.workbook=await GBXlsx.open(file);
        const sheets=state.workbook.sheets.filter(s=>/JE/i.test(s.name));
        if(!sheets.length)throw Error(t('No journal worksheet found. Use a CSV with the R365 journal columns.','No se encontró una hoja de pólizas. Usa un CSV con las columnas R365.'));
        el('file-options').innerHTML=`<label class="form-field" style="margin-top:18px">${t('Journal worksheet','Hoja de póliza')}<select id="xlsx-sheet">${sheets.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select><small>${t('Only the selected worksheet will be read.','Sólo se leerá la hoja seleccionada.')}</small></label>`;
        el('import-kind').value='sales';state.importType='sales';
      }
      el('read-file-btn').disabled=false;
    }catch(e){el('upload-error').innerHTML=`<div class="error-box">${esc(e.message)}</div>`;el('read-file-btn').disabled=true;}
  }
  async function readFile(){
    const f=state.pendingFile;if(!f)return;el('read-file-btn').disabled=true;
    try{
      const kind=el('import-kind').value;let result;
      if(state.workbook){if(kind!=='sales')throw Error(t('This XLSX reader is for sales journals.','El lector XLSX es para pólizas de ventas.'));result=await state.workbook.readSheet(el('xlsx-sheet').value);}
      else{
        result=C.parseCSV(await f.text());const expected=kind==='ap'?C.AP_HEADERS:C.JE_HEADERS;const missing=expected.filter(h=>!result.headers.includes(h));
        if(missing.length)throw Error(t('Missing columns: ','Faltan columnas: ')+missing.join(', '));
        if(kind==='sales'){result.invoices=[];result.sheet=f.name;}
      }
      if(result.rows.length>20000)throw Error(t('Preview limit: 20,000 rows.','Límite de vista previa: 20,000 filas.'));
      const normalized=rows=>JSON.stringify(rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k])=>!k.startsWith('_')).sort(([a],[b])=>a.localeCompare(b)))));
      const original=kind==='ap'?ap().rows:sales().rows;
      if(normalized(result.rows)===normalized(original)){el('modal').close();nav(kind);toast(t('This exact batch is already loaded. No duplicate was added.','Este lote ya está cargado. No se agregó un duplicado.'));addEvent(t('Duplicate skipped','Duplicado omitido'),f.name);return;}
      const sum=kind==='ap'?C.summarizeAP(result.rows):C.summarizeJE(result.rows);
      const errors=sum.issues.filter(i=>i.level==='error');if(errors.length)throw Error(t(`${errors.length} validation issues. First: `,`${errors.length} problemas de validación. Primero: `)+errors[0].code+(errors[0].row?` · ${t('row','fila')} ${errors[0].row}`:''));
      result.source=f.name;result.id='upload-'+Date.now();state.uploaded[kind]=result;
      addEvent(t('File read locally','Archivo leído localmente'),`${f.name} · ${result.rows.length} ${t('rows','filas')}`);el('modal').close();nav(kind);toast(t('File loaded. Review the figures before export.','Archivo cargado. Revisa los importes antes de exportar.'));
    }catch(e){el('upload-error').innerHTML=`<div class="error-box">${esc(e.message)}</div>`;el('read-file-btn').disabled=false;}
  }
  function reviewDialog(){const kind=currentKind(),codes=issues(kind),key=batchKey(kind),list=summary(kind).issues;showDialog(t('Review source checkpoints','Revisar puntos del origen'),`<p class="notice">${t('These checks do not change the source values. Marking them reviewed is a demonstration, not accounting approval.','Estos controles no modifican los valores originales. Marcar su revisión es una demostración, no una aprobación contable.')}</p>${codes.map(code=>`<section class="review-card"><h3>${issueTitle(code)}</h3><p>${issueDescription(code)}</p><p style="margin-top:8px">${code==='negative'?t('Negative amounts are preserved exactly as supplied. Confirm their accounting treatment with the reviewer.','Los importes negativos se conservan como en el origen. Confirmar el tratamiento contable con la persona revisora.'):code==='period'?periodReviewText():t('Multiple location codes appear in the source journal. Confirm before posting.','La póliza contiene varias ubicaciones. Confirmar antes de registrar.')}</p><p style="margin-top:6px;font-size:10px">${t('Source rows','Filas de origen')}: ${list.filter(i=>i.code===code).map(i=>i.row||'—').join(', ')}</p><label><input type="checkbox" data-review-code="${code}" ${(state.reviewed[key]||[]).includes(code)?'checked':''}>${t('I have reviewed this point in the demo.','He revisado este punto en la demo.')}</label></section>`).join('')}`,button(t('Cancel','Cancelar'),'close')+button(t('Save review notes','Guardar revisión'),'save-review','primary','check'));}
  function download(filename,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
  function exportPreview(){const kind=currentKind(),key=batchKey(kind);if(!state.approved[key]||!canApprove())return;const data=kind==='ap'?ap():sales();download(`GBtoR365_${kind==='ap'?'AP':'JE'}_PREVIEW.csv`,C.toCSV(kind==='ap'?C.AP_HEADERS:C.JE_HEADERS,data.rows));addEvent(t('Preview downloaded','Vista previa descargada'),`${kind.toUpperCase()} · ${data.rows.length} ${t('rows','filas')} · ${t('Not imported into R365','Sin importar a R365')}`);showDialog(t('Your preview is ready','Tu vista previa está lista'),`<div class="export-success"><div class="success-circle">${icon('download',25)}</div><h3>${t('Review copy downloaded','Copia de revisión descargada')}</h3><p>${t('The CSV uses the supplied R365 column layout. Original amounts, signs and comments are preserved. Nothing has been imported into R365.','El CSV utiliza las columnas R365 recibidas. Se conservan importes, signos y comentarios originales. No se ha importado nada a R365.')}</p></div>`,button(t('Back to workspace','Volver al proceso'),'close','primary'));}
  function detail(target){const group=summary('ap').groups.find(g=>g.number===target.dataset.number&&g.vendor===target.dataset.vendor&&g.location===target.dataset.location);if(!group)return;showDialog(`${t('Invoice','Factura')} ${esc(group.number)}`,`<div class="detail-summary"><div><small>${t('VENDOR','PROVEEDOR')}</small><strong>${esc(group.vendor)}</strong></div><div><small>${t('LOCATION','UBICACIÓN')}</small><strong>${esc(group.location)}</strong></div><div><small>${t('INVOICE TOTAL','TOTAL FACTURA')}</small><strong>${money(group.amount)}</strong></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Account','Cuenta')}</th><th>${t('Amount','Importe')}</th><th>${t('Location','Ubicación')}</th></tr></thead><tbody>${group.rows.map(r=>`<tr><td>${esc(r['Detail Account'])}</td><td class="money">${money(C.cents(r['Detail Amount']))}</td><td>${esc(r['Detail Location'])}</td></tr>`).join('')}</tbody></table></div><div class="balance-box"><div class="balance-row"><span>${t('Invoice total','Total factura')}</span><b>${money(group.amount)}</b></div><div class="balance-row"><span>${t('Detail total','Total detalle')}</span><b>${money(group.detail)}</b></div></div>`,button(t('Close','Cerrar'),'close','primary'));}
  function profileDialog(){if(SESSION){showDialog(t('Your account','Tu cuenta'),`<p class="notice"><strong>${esc(SESSION.name)}</strong><br>${esc(SESSION.email)}<br>${roleLabel(SESSION.role)}</p><p class="small-note">${t('You are signed in with your Artimex account. Accounting workflows remain a preview.','Has iniciado sesión con tu cuenta de Artimex. Los procesos contables siguen en vista previa.')}</p>`,button(t('Close','Cerrar'),'close')+button(t('Sign out','Cerrar sesión'),'logout','primary'));return;}showDialog(t('Try a preview profile','Probar un perfil'),`<p class="notice">${t('Proposed roles for the future application. No account is created and no email is sent.','Roles propuestos para la aplicación futura. No se crean cuentas ni se envían correos.')}</p>${D.users.map((u,i)=>`<button class="user-choice ${state.user===i?'selected':''}" data-action="choose-profile" data-user="${i}">${initials(i)}<span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span>${pill(roleLabel(state.roles[i]||u.role),'outline')}</button>`).join('')}`);}
  document.addEventListener('click',e=>{
    const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();nav(navEl.dataset.nav);return;}
    const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;state.page=0;state.query='';render();return;}
    const target=e.target.closest('[data-action]');if(!target)return;
    const action=target.dataset.action,kind=currentKind(),key=batchKey(kind);
    if(!actionAllowed(action)){toast(t('This action is not available with your access.','Esta acción no está disponible con tu acceso.'));return;}
    if(action==='language'){state.lang=state.lang==='en'?'es':'en';try{localStorage.setItem('gbtor365-language',state.lang);}catch{}render();}
    else if(action==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-scrim').classList.toggle('open');}
    else if(action==='go-ap')nav('ap');else if(action==='go-sales')nav('sales');
    else if(action==='import')openImport(target.dataset.kind||'ap');
    else if(action==='close')el('modal').close();
    else if(action==='profile')profileDialog();
    else if(action==='logout'){fetch('/api/logout',{method:'POST',credentials:'same-origin'}).then(response=>{if(!response.ok)throw Error();location.replace('/login');}).catch(()=>toast(t('Unable to sign out. Please try again.','No se pudo cerrar sesión. Inténtalo de nuevo.')));}
    else if(action==='choose-profile'){if(SESSION)return;state.user=Number(target.dataset.user);el('modal').close();render();toast(t('Preview profile changed.','Perfil de demostración cambiado.'));}
    else if(action==='use-sample'){const k=el('import-kind').value;state.uploaded[k]=null;el('modal').close();nav(k);toast(t('Demo sample loaded.','Ejemplo de demostración cargado.'));}
    else if(action==='read-file')readFile();
    else if(action==='page-prev'||action==='page-next'){state.page+=action==='page-prev'?-1:1;el('records-region').innerHTML=records();}
    else if(action==='detail')detail(target);
    else if(action==='review')reviewDialog();
    else if(action==='save-review'){state.reviewed[key]=[...el('modal').querySelectorAll('[data-review-code]:checked')].map(c=>c.dataset.reviewCode);state.approved[key]=false;addEvent(t('Checkpoints reviewed','Puntos revisados'),`${kind.toUpperCase()} · ${state.reviewed[key].length}`);el('modal').close();render();toast(t('Review notes saved for this demo.','Revisión guardada en esta demo.'));}
    else if(action==='validate'){state.validated[key]=true;state.approved[key]=false;const errors=summary(kind).issues.filter(i=>i.level==='error');addEvent(t('Batch validated','Lote validado'),`${kind.toUpperCase()} · ${errors.length} ${t('blocking errors','errores bloqueantes')}`);render();toast(errors.length?t('Check the validation errors.','Revisa los errores de validación.'):t('Totals checked. Review any remaining checkpoints.','Totales comprobados. Revisa los puntos pendientes.'));}
    else if(action==='approve'){if(!state.validated[key]||!allReviewed(kind)||!canApprove()||summary(kind).issues.some(i=>i.level==='error'))return;showDialog(t('Approve the export preview','Aprobar la vista de exportación'),`<p class="notice">${t('This action approves the demonstration workflow only. It does not post entries, change the source, or connect to R365.','Esta acción aprueba únicamente el proceso de demostración. No registra asientos, modifica el origen ni se conecta a R365.')}</p><div class="info-strip">${icon('shield',17)}${t('Original values and review checkpoints remain visible in the export preview.','Los valores originales y puntos de revisión permanecen visibles en la vista de exportación.')}</div><label class="approval-box"><input id="approve-confirm" type="checkbox">${t('I have reviewed the figures and understand this is a preview copy.','He revisado los importes y entiendo que es una copia de vista previa.')}</label>`,button(t('Cancel','Cancelar'),'close')+button(t('Approve preview','Aprobar vista previa'),'confirm-approve','primary','check','id="approve-btn" disabled'));}
    else if(action==='confirm-approve'){if(!el('approve-confirm')?.checked||!canApprove())return;state.approved[key]=true;addEvent(t('Preview approved','Vista previa aprobada'),kind.toUpperCase());el('modal').close();render();toast(t('Preview approved. Download is available.','Vista aprobada. Ya puedes descargarla.'));}
    else if(action==='export')exportPreview();
    else if(action==='download-log'){download('GBtoR365_DEMO_LOG.csv',C.toCSV(['time','action','detail','user'],state.events));toast(t('Session log downloaded.','Historial de sesión descargado.'));}
    else if(action==='edit-role'){const i=Number(target.dataset.user);showDialog(t('Edit proposed role','Editar rol propuesto'),`<p class="notice">${esc(D.users[i].name)} · ${esc(D.users[i].email)}</p><label class="form-field">${t('Proposed role','Rol propuesto')}<select id="role-select">${['reviewer','preparer','finance','admin'].map(r=>`<option value="${r}" ${r===(state.roles[i]||D.users[i].role)?'selected':''}>${roleLabel(r)}</option>`).join('')}</select><small>${t('Preview setting only. No production permission is changed.','Sólo configuración de demo. No cambia permisos de producción.')}</small></label>`,button(t('Cancel','Cancelar'),'close')+button(t('Save proposed role','Guardar rol propuesto'),'save-role','primary','check',`data-user="${i}"`));}
    else if(action==='save-role'){state.roles[Number(target.dataset.user)]=el('role-select').value;el('modal').close();render();toast(t('Proposed role updated.','Rol propuesto actualizado.'));}
    else if(action==='reset'){showDialog(t('Reset the demo?','¿Reiniciar la demo?'),`<p class="notice">${t('Clear this tab’s uploaded batches, review notes and activity. The original supplied samples will be restored.','Borrar los lotes cargados, revisiones e historial de esta pestaña. Se restaurarán los ejemplos originales.')}</p>`,button(t('Cancel','Cancelar'),'close')+button(t('Reset demo','Reiniciar demo'),'confirm-reset','primary','reset'));}
    else if(action==='confirm-reset'){Object.assign(state,{uploaded:{ap:null,sales:null},validated:{},approved:{},reviewed:{},events:[],roles:{},week:0,user:SESSION?Math.max(0,D.users.findIndex(u=>u.email===SESSION.email)):0});el('modal').close();nav('overview');toast(t('Original samples restored.','Ejemplos originales restaurados.'));}
  });
  document.addEventListener('input',e=>{if(e.target.id==='table-search'){state.query=e.target.value;state.page=0;el('records-region').innerHTML=records();}});
  document.addEventListener('change',e=>{if(e.target.id==='week-select'){state.week=Number(e.target.value);state.page=0;state.query='';render();}else if(e.target.id==='upload-file')selectFile(e.target.files[0]);else if(e.target.id==='approve-confirm')el('approve-btn').disabled=!e.target.checked;});
  document.addEventListener('dragover',e=>{const drop=e.target.closest('#dropzone');if(drop){e.preventDefault();drop.classList.add('drag');}});
  document.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('drag'));
  document.addEventListener('drop',e=>{const drop=e.target.closest('#dropzone');if(drop){e.preventDefault();drop.classList.remove('drag');selectFile(e.dataTransfer.files[0]);}});
  el('modal').addEventListener('click',e=>{if(e.target===el('modal')){const r=el('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el('modal').close();}});
  window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(labels[v]&&v!==state.view)nav(v);});
  if(labels[location.hash.slice(1)])state.view=location.hash.slice(1);
  render();
})();
